script.code:
let allData = {{workflowparams:allData}}
const filterZero = {{workflowparams:filter_zero}}
const updatedSM = []
const saveAs = {{workflowparams:saveAs}}

// Helper function to format qty and price fields to 3 decimal places
const formatNumber = (value) => {
  if (value === null || value === undefined || value === "") return 0;
  return parseFloat(value).toFixed(3);
};

for (const [index, smLineItem] of allData.stock_movement.entries()) {
  // Format qty and price fields
  smLineItem.requested_qty = formatNumber(smLineItem.requested_qty);
  smLineItem.total_quantity = formatNumber(smLineItem.total_quantity);
  smLineItem.unit_price = formatNumber(smLineItem.unit_price);

  smLineItem.organization_id = allData.organization_id;
  smLineItem.issuing_plant = allData.issuing_operation_faci || null;
  smLineItem.receiving_plant = allData.receiving_operation_faci || null;
  smLineItem.line_index = index + 1;

  updatedSM.push(smLineItem)
}

allData.stock_movement = updatedSM

if (filterZero === 'Yes') {
  allData.stock_movement = allData.stock_movement.filter(item => item.total_quantity && parseFloat(item.total_quantity) > 0)
}

allData.po_id = [...new Set(allData.stock_movement.map((sm) => sm.po_id).filter(poID => poID))]
if ({{workflowparams:pageStatus}} === "Add") {
  allData.stock_movement_status = "Draft"
}

if (saveAs === "Draft") {
  if(allData.stock_movement_no_type !== -9999 && (
  !allData.stock_movement_no || allData.stock_movement_no === null || allData.stock_movement_no === ''
)) {
  allData.stock_movement_no = 'draft'
  }
} else {
  if (
  allData.stock_movement_no_type !== -9999 &&
  (!allData.stock_movement_no ||
    allData.stock_movement_no === null ||
    allData.stock_movement_no === "" ||
    allData.stock_movement_status !== "In Progress")
) {
  allData.stock_movement_no = 'issued'
  }
}

if (allData.acc_integration_type !== "No Accounting Integration") {
  allData.posted_status = "Unposted";
} else {
  allData.posted_status = "";
}

return {
  allData: allData,
  stock_movement_status: allData.stock_movement_status,
}

return {
  required_fields: JSON.stringify([
  { name: "stock_movement_no", label: "Stock Movement No" },
  { name: "movement_type", label: "Movement Type" },
  { name: "issue_date", label: "Issue Date" },
  { name: "issuing_operation_faci", label: "Issuing Operation Facility" },
  {
    name: "stock_movement",
    label: "Item Information",
    isArray: true,
    arrayType: "object",
    arrayFields: [],
  },
]),
  data: JSON.stringify({
    stock_movement_no: {{node:code_node_ISWz5KGY.data.allData.stock_movement_no}},
    movement_type: {{node:code_node_ISWz5KGY.data.allData.movement_type}},
    issue_date: {{node:code_node_ISWz5KGY.data.allData.issue_date}},
    issuing_operation_faci: {{node:code_node_ISWz5KGY.data.allData.issuing_operation_faci}},
    stock_movement: {{node:code_node_ISWz5KGY.data.allData.stock_movement}}
  })
}

const saveAs = {{workflowparams:saveAs}};
const pageStatus = {{workflowparams:pageStatus}};

const rows = {{node:search_node_MSIspLive.data.data}};
const arr = Array.isArray(rows) ? rows : (rows ? [rows] : []);

// Draft/Completed/Cancelled pickings are not work in progress. Anything else is a
// picker's open work list, and the movement has no reconcile path -- editing it
// would leave the two out of step -- so block BEFORE anything is persisted.
// Only the "Created" re-save is gated: advancing or cancelling the movement stays
// open, and the auto-advance call from STOCK_PICKING_PROCESS sends "In Progress",
// so it exempts itself.
const active = arr.filter((p) => p &&
  p.sp_status !== "Draft" && p.sp_status !== "Completed" && p.sp_status !== "Cancelled");

let blocked = 0;
let guardMessage = "";
if (saveAs === "Created" && pageStatus === "Edit" && active.length > 0) {
  blocked = 1;
  const list = active.map((p) => p.sp_id || p.id).slice(0, 5).join(", ");
  const more = active.length > 5 ? " (+" + (active.length - 5) + " more)" : "";
  guardMessage =
    "Cannot edit this Misc Issue while " + active.length +
    (active.length === 1 ? " Stock Picking is" : " Stock Pickings are") +
    " active: " + list + more + ". Cancel or complete " +
    (active.length === 1 ? "it" : "them") + " first.";
}

return { blocked: blocked, guardMessage: guardMessage };

const allData = {{node:code_node_ISWz5KGY.data.allData}}
const subformData = allData.stock_movement || []
const filterZero = {{workflowparams:filter_zero}};

let quantityFailed = 0
let quantityMessage

for (let i = 0; i < subformData.length; i++) {
  const item = subformData[i];

  let lineHasQty = false;
  if (item.temp_qty_data) {
    try {
      const parsed = JSON.parse(item.temp_qty_data);
      lineHasQty = Array.isArray(parsed) && parsed.some(
        (entry) => entry.sm_quantity && parseFloat(entry.sm_quantity) > 0
      );
    } catch (e) {
      lineHasQty = false;
    }
  }

  if (!lineHasQty && filterZero === 'No') {
    quantityFailed = 1;
    quantityMessage = `Quantity is required for item ${i + 1} in Miscellaneous Issue`;
    break;
  }
}

return {
  quantityFailed: quantityFailed,
  quantityMessage: (quantityMessage || '') + '<br><br>If proceed, it will remove the line.'
};

const page_status = {{workflowparams:pageStatus}};
const allData = {{node:code_node_ISWz5KGY.data.allData}}

const subformData = allData.stock_movement;

const plant_id = allData.issuing_operation_faci;
const organization_id = allData.organization_id;
const stock_movement_no = allData.stock_movement_no;
const doc_date = allData.issue_date;

const item = {{node:loop_C4YuLV2v}};
const material_id = item.item_selection;
const material_uom = item.quantity_uom || item.received_quantity_uom;
const total_quantity = item.total_quantity;
const location_id = item.location_id;
const batch_id = item.batch_id || null;
const inventory_category = "Unrestricted";

let balancesToProcess = [];
const tempData = item.temp_qty_data;
if (tempData) {
  try {
    const parsed = JSON.parse(tempData);
    if (Array.isArray(parsed)) {
      balancesToProcess = parsed.filter(
        (entry) => entry.sm_quantity && parseFloat(entry.sm_quantity) > 0
      );
    }
  } catch (e) {
    balancesToProcess = [];
  }
}

return {
  plant_id: plant_id,
  organization_id: organization_id,
  stock_movement_no: stock_movement_no,
  page_status: page_status,
  material_id: material_id,
  material_uom: material_uom,
  total_quantity: total_quantity,
  location_id: location_id,
  batch_id: batch_id,
  inventory_category: inventory_category,
  doc_date: doc_date,
  balancesToProcess: balancesToProcess
};

const balance = {{node:loop_9XodkC0Z}};
const batch_id = balance.batch_id || null;
const location_id = balance.location_id;
const quantity = balance.sm_quantity;
const inventory_category = balance.category;
const manufacturing_date = balance.manufacturing_date || null;
const expired_date = balance.expired_date || null;
const handling_unit_id = balance.handling_unit_id || null;

return {
  batch_id: batch_id,
  location_id: location_id,
  quantity: quantity,
  inventory_category: inventory_category,
  manufacturing_date: manufacturing_date,
  expired_date: expired_date,
  handling_unit_id: handling_unit_id
};

// One batched Item fetch for the whole subform (was: one get-node per line,
// inside the loop). Mirrors the dedup already used by updateItemTransactionDate.
const tableSM = {{node:code_node_ISWz5KGY.data.allData.stock_movement}} || [];
const itemIDs = [...new Set(tableSM.filter(i => i.item_selection).map(i => i.item_selection))];
return { itemIDs: itemIDs };

const pageStatus = {{workflowparams:pageStatus}};
let docId = "";
if (pageStatus === "Add") {
  const rd = {{node:add_node_1p1Kdkhz.data}};
  const rec = Array.isArray(rd) ? rd[0] : rd;
  docId = (rec && rec.id) ? rec.id : "";
} else {
  docId = {{node:code_node_ISWz5KGY.data.allData.id}} || "";
}
return { docId: docId };

const roundQty = (v) => parseFloat(parseFloat(v || 0).toFixed(3));
const qtyStr = (v) => Math.max(0, roundQty(v)).toFixed(3);

const pageStatus = {{workflowparams:pageStatus}};
let allData;
if (pageStatus === "Add") {
  const rd = {{node:add_node_1p1Kdkhz.data}};
  allData = Array.isArray(rd) ? rd[0] : rd;
} else {
  allData = {{node:get_node_7CFMbGI0.data.data}};
}

const lines = allData.stock_movement || [];
// doc_line_id fix (same class as GR/LOT): on a fresh (Add) save the add-node
// response carries no subform row ids, so line.id is empty. Resolve each line's
// id from the persisted re-read by its line_index.
const persistedRaw = {{node:get_node_MSIspDoc.data.data}};
const persistedRec = Array.isArray(persistedRaw) ? persistedRaw[0] : persistedRaw;
const persistedLines = (persistedRec && persistedRec.stock_movement) ? persistedRec.stock_movement : [];
const idByLineIdx = {};
persistedLines.forEach((r, i) => {
  const k = (r.line_index === undefined || r.line_index === null || r.line_index === "") ? String(i + 1) : String(r.line_index);
  if (r.id) idByLineIdx[k] = r.id;
});
const plantId = allData.issuing_operation_faci;
const orgId = allData.organization_id;
const docId = allData.id || "";
const docNo = allData.stock_movement_no || "";
const docDate = allData.issue_date;

// RESERVE is an idempotent rebuild: release every open hold back to its source
// category, then re-reserve from the current lines.
const resRaw = {{node:search_node_MSIresOpen.data.data}};
const resAll = Array.isArray(resRaw) ? resRaw : (resRaw ? [resRaw] : []);
const resRows = resAll.filter((r) => r && r.status === "Allocated");

const RESERVED = "Reserved";
const fromCatOf = (r) => r.from_category || "Unrestricted";
const releaseMovements = [];
const movements = [];
const reserveCreates = [];
const reserveUpdates = [];
const materialSet = {};

for (const r of resRows) {
  const q = roundQty(r.open_qty);
  if (q > 0) {
    materialSet[r.material_id] = true;
    releaseMovements.push({
      material_id: r.material_id, batch_id: r.batch_id || null, quantity: q,
      material_uom: r.item_uom, handling_unit_id: r.handling_unit_id || null,
      manufacturing_date: null, expired_date: null,
      subtractCategory: RESERVED, subtractLocation: r.bin_location,
      addCategory: fromCatOf(r), addLocation: r.bin_location,
    });
  }
  reserveUpdates.push({
    id: r.id, delivered_qty: qtyStr(r.delivered_qty), open_qty: qtyStr(0), status: "Cancelled",
  });
}

for (const line of lines) {
  let entries = [];
  try { entries = JSON.parse(line.temp_qty_data || "[]"); } catch (e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];
  for (const e of entries) {
    const qty = roundQty(e.sm_quantity);
    if (qty <= 0) continue;
    const mat = e.material_id || line.item_selection;
    const C = e.category || "Unrestricted";
    materialSet[mat] = true;
    // Misc Issue has no destination bin: the hold changes category in place.
    movements.push({
      material_id: mat, batch_id: e.batch_id || null, quantity: qty,
      material_uom: e.material_uom || line.quantity_uom,
      handling_unit_id: e.handling_unit_id || null,
      manufacturing_date: e.manufacturing_date || null, expired_date: e.expired_date || null,
      subtractCategory: C, subtractLocation: e.location_id,
      addCategory: RESERVED, addLocation: e.location_id,
    });
    reserveCreates.push({
      doc_type: "Miscellaneous Issue", doc_id: docId, doc_no: docNo,
      doc_line_id: line.id || idByLineIdx[String(line.line_index)] || "", line_no: line.line_index,
      parent_id: "", parent_no: "", parent_line_id: "",
      material_id: mat, item_code: "", item_name: "", item_desc: "",
      item_uom: e.material_uom || line.quantity_uom,
      batch_id: e.batch_id || null, handling_unit_id: e.handling_unit_id || null,
      bin_location: e.location_id, from_category: C,
      reserved_qty: qtyStr(qty), delivered_qty: qtyStr(0), open_qty: qtyStr(qty),
      status: "Allocated", reserved_date: docDate,
      plant_id: plantId, organization_id: orgId,
      remark: line.item_remark || "", target_gd_id: "", source_reserved_id: "",
    });
  }
}

const allMovements = releaseMovements.concat(movements).filter(
  (m) => !(m.subtractCategory === m.addCategory && String(m.subtractLocation) === String(m.addLocation))
);

return {
  movements: allMovements, movementsLength: allMovements.length,
  materialIds: Object.keys(materialSet),
  reserveCreates, hasReserveCreates: reserveCreates.length > 0 ? 1 : 0,
  reserveUpdates, hasReserveUpdates: reserveUpdates.length > 0 ? 1 : 0,
  plant_id: plantId, organization_id: orgId, stock_movement_no: docNo, doc_date: docDate,
};

const m = {{node:loop_MSIresMove}} || {};
const items = {{node:search_node_MsiItems.data.data}} || [];
const list = Array.isArray(items) ? items : [items];
const itemData = list.find((i) => i && String(i.id) === String(m.material_id)) || null;
return {
  material_id: m.material_id, quantity: m.quantity, material_uom: m.material_uom,
  batch_id: m.batch_id || null, handling_unit_id: m.handling_unit_id || null,
  manufacturing_date: m.manufacturing_date || null, expired_date: m.expired_date || null,
  subtractCategory: m.subtractCategory, subtractLocation: m.subtractLocation,
  addCategory: m.addCategory, addLocation: m.addLocation, itemData,
};

const roundQty = (v) => Math.round((parseFloat(v) || 0) * 1000) / 1000;
const qtyNum = (v) => Math.max(0, roundQty(v));

const saveAs = {{workflowparams:saveAs}};
const empty = { needsCreate: 0, createData: {}, srcIds: [], lineIds: [], pickingStatus: "" };
if (saveAs !== "Created") return empty;

// Re-read the PERSISTED document. A fresh save's add-node response carries no
// subform row ids, so building the picking off it would leave every src_line_id
// blank and the Stock Picking would have no way back to the movement line.
const raw = {{node:get_node_MSIspDoc.data.data}};
const allData = Array.isArray(raw) ? raw[0] : raw;
if (!allData) return empty;

const docId = String(allData.id || "");
const docNo = allData.stock_movement_no || "";

// One Stock Picking per movement. The reservation rebuild above is idempotent,
// this is not -- an existing non-Cancelled picking short-circuits the build so a
// re-save of a Created document cannot mint a second one.
const existRaw = {{node:search_node_MSIspLive.data.data}};
const existAll = Array.isArray(existRaw) ? existRaw : (existRaw ? [existRaw] : []);
if (existAll.filter((p) => p && p.sp_status !== "Cancelled").length > 0) return empty;

const ruleRaw = {{node:get_node_MSIspRule.data.data}};
const rule = Array.isArray(ruleRaw) ? ruleRaw[0] : ruleRaw;
// -9999 is the platform's "no numbering rule" sentinel -- the same one
// StockPickingLoopWorkflow tests before it asks for a generated number. Without a
// "Stock Picking" prefix for this organisation the document is created unnumbered
// rather than not at all, so the pick is never silently lost.
const ruleId = rule && rule.id ? rule.id : -9999;

// One picking row per (item, batch, bin, movement line, HU) -- the same grouping the
// GD path uses, so two allocations that differ only by bin stay separately pickable.
const groups = new Map();
const lineIds = [];

for (const line of allData.stock_movement || []) {
  let entries = [];
  try { entries = JSON.parse(line.temp_qty_data || "[]"); } catch (e) { entries = []; }
  if (!Array.isArray(entries)) entries = [];
  let lineHasWork = 0;
  for (const e of entries) {
    const qty = qtyNum(e.sm_quantity);
    if (qty <= 0) continue;
    const mat = e.material_id || line.item_selection;
    if (!mat) continue;
    const uom = e.material_uom || line.quantity_uom;
    const key = [
      String(mat), String(e.batch_id || "no-batch"), String(e.location_id || "no-bin"),
      String(line.id || ""), String(e.handling_unit_id || "no-hu"),
    ].join("|");
    let g = groups.get(key);
    if (!g) {
      g = {
        row_type: "item", hu_select: 0,
        handling_unit_id: e.handling_unit_id || null,
        item_code: String(mat),
        item_name: line.item_name || "",
        item_desc: line.item_desc || "",
        more_desc: "",
        src_no: docNo,
        batch_no: e.batch_id || null,
        target_batch: null,
        qty_to_pick: 0, to_pick_alt: 0,
        pending_process_qty: 0, pending_alt: 0, picked_qty: 0,
        // Identity conversion. enrichPickingUOM() in SPonMounted recomputes both
        // scalars and both alt columns from the item master every time the Stock
        // Picking is opened, so seeding them 1:1 is correct rather than merely safe.
        order_base_qty: 1, picking_base_qty: 1,
        item_uom: uom, picking_uom: uom,
        source_bin: e.location_id || null,
        line_status: "Open",
        net_weight: 0, weight_conversion: 0,
        project_id: line.project_id || null,
        src_id: docId, src_line_id: String(line.id || ""),
        is_serialized_item: 0,
        serialList: [],
      };
      groups.set(key, g);
    }
    g.qty_to_pick = roundQty(g.qty_to_pick + qty);
    if (e.serial_number) g.serialList.push(String(e.serial_number));
    lineHasWork = 1;
  }
  if (lineHasWork && line.id) lineIds.push(String(line.id));
}

const tablePickingItems = [];
groups.forEach((g) => {
  g.pending_process_qty = g.qty_to_pick;
  g.to_pick_alt = g.qty_to_pick;
  g.pending_alt = g.qty_to_pick;
  if (g.serialList.length > 0) {
    g.is_serialized_item = 1;
    g.serial_numbers = g.serialList.join(", ");
  }
  delete g.serialList;
  tablePickingItems.push(g);
});

// Nothing allocated means nothing to pick -- a description-only document must not
// spawn an empty picking the warehouse can never complete.
if (tablePickingItems.length === 0) return empty;

const createData = {
  sp_status: "Created",
  sp_id: ruleId === -9999 ? "" : "issued",
  sp_id_type: ruleId,
  plant_id: allData.issuing_operation_faci,
  organization_id: allData.organization_id,
  movement_type: "Picking",
  ref_doc_type: "Miscellaneous Issue",
  src_id: docId,
  src_no: docNo,
  assigned_to: [],
  ref_doc: [],
  created_at: allData.issue_date,
  created_by: allData.issued_by || "",
  is_processing: 0,
  project_id: allData.project_id || null,
  remarks: allData.remarks || "",
  remarks_2: allData.remark2 || "",
  remarks_3: allData.remark3 || "",
  table_picking_items: tablePickingItems,
  table_picking_records: [],
};

return {
  needsCreate: 1, createData: createData,
  srcIds: [docId], lineIds: lineIds, pickingStatus: "Created",
};

const page_status = {{workflowparams:pageStatus}};
const stock_movement_status = {{node:code_node_ISWz5KGY.data.stock_movement_status}}
let allData;

if (page_status === "Add") {
  const rawData = {{node:add_node_1p1Kdkhz.data}}
  allData = Array.isArray(rawData) ? rawData[0] : rawData;
} else if (page_status === "Edit") {
  allData = {{node:get_node_7CFMbGI0.data.data}}
} else {
  allData = {{node:code_node_ISWz5KGY.data.allData}}
}

const plant_id = allData.issuing_operation_faci;
const organization_id = allData.organization_id;
const stock_movement_no = allData.stock_movement_no;
const doc_date = allData.issue_date;

// Current subform row comes straight from the loop variable — no redis index
// counter (the old counter was keyed only on issued_by, so two concurrent saves
// by the same user corrupted each other's index).
const item = {{node:loop_BBZNjfzE}};
const material_id = item.item_selection;
const material_uom = item.quantity_uom || item.received_quantity_uom;
const total_quantity = item.total_quantity;
const location_id = item.location_id;
const batch_id = item.batch_id || null;
const remark = item.item_remark || null;
const remark2 = item.item_remark_2 || null;
const remark3 = item.item_remark_3 || null;
const poNO = item.po_no || null;
const inventory_category = "Unrestricted";

let balancesToProcess = [];
const tempData = item.temp_qty_data;
if (tempData) {
  try {
    const parsed = JSON.parse(tempData);
    if (Array.isArray(parsed)) {
      balancesToProcess = parsed.filter(
        (entry) => entry.sm_quantity && parseFloat(entry.sm_quantity) > 0
      );
    }
  } catch (e) {
    balancesToProcess = [];
  }
}

// Map poNO into each balance entry
balancesToProcess = balancesToProcess.map(entry => ({
  ...entry,
  po_no: poNO
}));

// itemData for SUBTRACT_INVENTORY, picked from the single batched Item fetch
// (previously one get-node per subform line, inside this loop).
const itemsRaw = {{node:search_node_MsiItems.data.data}} || [];
const itemsArr = Array.isArray(itemsRaw) ? itemsRaw : [itemsRaw];
const itemData = itemsArr.find(i => i && String(i.id) === String(material_id)) || null;

return {
  plant_id: plant_id,
  organization_id: organization_id,
  stock_movement_no: stock_movement_no,
  page_status: page_status,
  material_id: material_id,
  material_uom: material_uom,
  total_quantity: total_quantity,
  location_id: location_id,
  batch_id: batch_id,
  inventory_category: inventory_category,
  doc_date: doc_date,
  remark: remark,
  remark2: remark2,
  remark3: remark3,
  balancesToProcess: balancesToProcess,
  itemData: itemData
};

const balance = {{node:loop_NWeT5dSb}};
const saveAs = {{workflowparams:saveAs}}
const stock_movement_status = {{node:code_node_ISWz5KGY.data.stock_movement_status}}

const batch_id = balance.batch_id || null;
const location_id = balance.location_id;
const quantity = balance.sm_quantity;
let inventory_category = balance.category;
// A document held at Created already moved its stock into Reserved in place, so
// the issue draws down Reserved rather than the line's original category.
if (stock_movement_status === "Created") inventory_category = "Reserved";
const manufacturing_date = balance.manufacturing_date || null;
const expired_date = balance.expired_date || null;
const po_no = balance.po_no || null;
const handling_unit_id = balance.handling_unit_id || null;

return {
  batch_id: batch_id,
  location_id: location_id,
  quantity: quantity,
  inventory_category: inventory_category,
  manufacturing_date: manufacturing_date,
  expired_date: expired_date,
  po_no: po_no,
  handling_unit_id: handling_unit_id
};

const allData = {{node:code_node_ISWz5KGY.data.allData}};
const subformData = allData.stock_movement || [];
const plantId = allData.issuing_operation_faci;
const organizationId = allData.organization_id;

const huUpdatesMap = new Map();
for (const line of subformData) {
  if (!line.temp_qty_data) continue;
  let entries;
  try {
    entries = JSON.parse(line.temp_qty_data);
  } catch (e) {
    continue;
  }
  if (!Array.isArray(entries)) continue;

  for (const entry of entries) {
    const huId = entry.handling_unit_id;
    if (!huId) continue;
    const qty = parseFloat(entry.sm_quantity || 0);
    if (qty <= 0) continue;

